<script lang="ts">
  import {onMount} from 'svelte';
  import {t} from '../lib/i18n';
  import {call} from '../lib/api';
  import {parseCareConfig,parseCarePreferences,type CareConfig,type CarePreferences} from '../lib/life-care';
  let {botId,disabled=false,onDirtyChange,onBusyChange}:{botId:string;disabled?:boolean;onDirtyChange?:(dirty:boolean)=>void;onBusyChange?:(busy:boolean)=>void}=$props();
  let snapshot=$state<CarePreferences>(),draft=$state<CareConfig>(),pending=$state(false),error=$state(''),message=$state('');
  let alive=false,epoch=0;
  const uid=$props.id();
  const dirty=$derived(!!draft&&!!snapshot&&JSON.stringify(draft)!==JSON.stringify(snapshot.config));
  $effect(()=>{onDirtyChange?.(dirty);});$effect(()=>{onBusyChange?.(pending);});
  async function refresh(){const id=botId,token=++epoch;try{const value=parseCarePreferences(await call('get_life_care_preferences',{botId:id}),id);if(alive&&id===botId&&token===epoch){snapshot=value;draft=structuredClone(value.config);error='';}}catch{if(alive&&id===botId)error='Die Selbstpflege-Einstellungen sind derzeit nicht verfügbar.';}}
  export async function saveDraft(){if(!draft||!snapshot||pending||disabled)return;const id=botId,revision=snapshot.revision,token=++epoch;pending=true;error='';try{const config=parseCareConfig(draft);const value=parseCarePreferences(await call('save_life_care_preferences',{botId:id,expectedRevision:revision,config}),id);if(value.revision!==revision+1)throw Error('care_invalid');if(alive&&id===botId&&token===epoch){snapshot=value;draft=structuredClone(value.config);message='Selbstpflege gespeichert. Ein neuer Life-Start bleibt ausdrücklich erforderlich.';}}catch{if(alive&&id===botId)error='Die Selbstpflege-Einstellungen wurden nicht bestätigt. Prüfe die Werte und lade neu.';}finally{if(alive)pending=false;}}
  export function discardDraft(){if(snapshot)draft=structuredClone(snapshot.config);}
  onMount(()=>{alive=true;void refresh();return()=>{alive=false;++epoch;onDirtyChange?.(false);onBusyChange?.(false);};});
</script>
<section class="settings-panel care"><details><summary>{$t('Selbstpflege fein abstimmen')}</summary><p class="note">{$t('Bedürfnisse verändern sich nur während einer bestätigten laufenden Life-Sitzung. Offline entsteht keine nachzuholende Schuld.')}</p>{#if error}<p role="alert" class="error">{$t(error)}</p>{/if}{#if message}<p role="status" class="note">{$t(message)}</p>{/if}{#if snapshot&&draft}<fieldset disabled={pending||disabled}><div class="needs">{#each ['Energie','Nahrung','Beschäftigung','Kontakt'] as label,index}<div><h3>{$t(label)}</h3><label for={`${uid}-priority-${index}`}>{$t('Wichtigkeit')}<input id={`${uid}-priority-${index}`} type="range" min="1" max="1000" step="1" bind:value={draft.priorities[index]}/></label><label for={`${uid}-threshold-${index}`}>{$t('Aktivität beginnen unter')}<input id={`${uid}-threshold-${index}`} type="range" min="1" max={draft.satisfiedAt[index]-1} step="1" bind:value={draft.startBelow[index]}/><output>{Math.round(draft.startBelow[index]/100)}%</output></label></div>{/each}</div><details><summary>{$t('Erweiterte Selbstpflege-Grenzen')}</summary><div class="advanced">{#each ['Energie','Nahrung','Beschäftigung','Kontakt'] as label,index}<label>{$t('Abnahme pro Minute')} · {$t(label)}<input type="number" min="0" max="1000" step="1" bind:value={draft.decayPerMinute[index]}/></label><label>{$t('Erholung pro bestätigter Aktivität')} · {$t(label)}<input type="number" min="1" max="5000" step="1" bind:value={draft.restoreUnits[index]}/></label>{/each}<label>{$t('Mindestdauer in Millisekunden')}<input type="number" min="1" max="600000" step="1" bind:value={draft.minimumDurationMs}/></label><label>{$t('Aktivitätspause in Millisekunden')}<input type="number" min="1" max="600000" step="1" bind:value={draft.cooldownMs}/></label><label>{$t('Wartezeit nach Hindernissen in Millisekunden')}<input type="number" min="1" max="600000" step="1" bind:value={draft.backoffMs}/></label></div></details></fieldset><p class="note">{$t('Änderungen beenden die aktuelle Life-Sitzung sicher und starten sie nicht erneut.')}</p><button class="button primary" disabled={!dirty||pending||disabled} onclick={saveDraft}>{$t('Selbstpflege speichern')}</button>{/if}</details></section>
<style>.care{margin-top:24px}summary{font-size:13px;cursor:pointer}.note{font-size:12px;color:var(--muted);line-height:1.7}.error{font-size:12px;color:var(--danger)}fieldset{border:0;padding:0;margin:0}.needs{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px;margin:20px 0}.needs h3{font-size:12px}.needs label{display:grid;font-size:11px;gap:8px;margin:14px 0}.needs output{color:var(--muted)}input[type=range]{padding:0;accent-color:var(--accent)}.advanced{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:20px 0}.advanced label{display:grid;gap:8px;font-size:11px}@media(max-width:760px){.needs{grid-template-columns:1fr 1fr}.advanced{grid-template-columns:1fr}}</style>
